function plan(size, hoursPerUnit, teamHoursPerWeek, contingencyPct) {
  var effortHours = Math.ceil(size * hoursPerUnit * (1 + contingencyPct / 100) - 1e-9);
  return { effortHours: effortHours, weeks: Math.ceil(effortHours / teamHoursPerWeek) };
}
// 140 × 6.5 = 910 h; +20% = 1092 h; team = 4 × 30 = 120 h/week ⇒ 9.1 ⇒ 10 weeks
const CLINIC_PLAN = plan(140, 6.5, 4 * 30, 20);
